function setMenu(open){const shell=$('.shell');if(!shell)return;if(open)menuReturn=document.activeElement;shell.classList.toggle('nav-open',open);const trigger=$('[data-action="menu"]');trigger?.setAttribute('aria-expanded',String(open));const workspace=$('.workspace');if(workspace)workspace.inert=open;document.body.style.overflow=open?'hidden':'';if(open)$('.sidebar-close')?.focus();else menuReturn?.focus();}
window.addEventListener('keydown',e=>{if(!$('.shell.nav-open'))return;if(e.key==='Escape'){e.preventDefault();setMenu(false);}if(e.key==='Tab'){const items=[...$('.sidebar').querySelectorAll('button,a[href]')].filter(x=>!x.disabled);if(e.shiftKey&&document.activeElement===items[0]){e.preventDefault();items.at(-1)?.focus();}else if(!e.shiftKey&&document.activeElement===items.at(-1)){e.preventDefault();items[0]?.focus();}}});
window.addEventListener('resize',()=>{if(innerWidth>980&&$('.shell.nav-open'))setMenu(false);});
function heading(title,sub,actions=''){return `<div class="page-heading"><div><p class="eyebrow">ZİYA ŞAKİR YILMAZ</p><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${actions}</div></div>`;}
function navigate(view){if(S.member?.must_change_password)return firstPasswordPage();if(!guard())return;setMenu(false);S.dirty=false;S.doc=null;S.search='';S.filter='all';S.view=view;S.tab='content';if(['books','talks','test','global'].includes(view)){const route={books:'/kitaplar/',talks:'/konusmaci/',test:'/testler/kafa-yapisi-testi/',global:'/_global/'}[view];const r=S.rows.find(x=>x.route===route);if(r){openEditor(r.id);if(view==='books'){const section=S.doc.sections.find(s=>s.groups.some(g=>isBookGroup(g,definition())));if(section){S.section=section.id;editor();}}return;}}render();}
function render(){if(S.doc)return editor();if(S.view==='dashboard')dashboard();else if(['pages','articles','notes','training'].includes(S.view))list();else if(S.view==='collections')collectionsPage();else if(S.view==='media')mediaPage();else if(S.view==='leads')leadsPage();else if(S.view==='team')teamPage();else settings();}
